(7208037, 1109574, 19825, '<td valign="top">Interesting image. I love the lighting.</td>', 'Interesting image. I love the lighting.', '2014-04-24 20:55:51.000000', NULL, 1),
(7208039, 1109574, 97225, '<td valign="top">Great image! Remarkable that such a small detail in the image plays such a pivotal role. One of my ribbon choices.</td>', 'Great image! Remarkable that such a small detail in the image plays such a pivotal role. One of my ribbon choices.', '2014-04-24 20:56:45.000000', NULL, 1),
(7208040, 1109636, 97225, '<td valign="top">Wonderful street scene. The light, especially the reflected light, is absolutely fabulous! I think that the perfect positioning of the clock has turned what would have been silhouette and blown light into this magical image.<br/>My choice for the blue.</td>', 'Wonderful street scene. The light, especially the reflected light, is absolutely fabulous! I think that the perfect positioning of the clock has turned what would have been silhouette and blown light into this magical image.My choice for the blue.', '2014-04-24 20:57:20.000000', NULL, 1),
(7208041, 1109584, 97225, '<td valign="top">Fascinating image, marvelous detail, beautiful tones. One of my ribbon choices..</td>', 'Fascinating image, marvelous detail, beautiful tones. One of my ribbon choices..', '2014-04-24 20:58:28.000000', NULL, 1),
(7208042, 1109475, 97225, '<td valign="top">Quite a work of art - the watch and the photo. Top 5.</td>', 'Quite a work of art - the watch and the photo. Top 5.', '2014-04-24 21:01:19.000000', NULL, 1),
