INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7208096, 1109540, 136989, '<td valign="top">The building looks regal and imposing. My favorite part though is the way the composition makes the clock faces look like eyes and the balcony (?)  look like a mouth.  I could see this building standing up and chasing after me (yes, I have had too much coffee today).  My favorite in this challenge.<br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=1082013" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/135000-139999/136989/120/Copyrighted_Image_Reuse_Prohibited_1082013.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/135000-139999/136989/120/Copyrighted_Image_Reuse_Prohibited_1082013.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/135000-139999/136989/120/Copyrighted_Image_Reuse_Prohibited_1082013.jpg"/></a></td>', 'The building looks regal and imposing. My favorite part though is the way the composition makes the clock faces look like eyes and the balcony (?)  look like a mouth.  I could see this building standing up and chasing after me (yes, I have had too much coffee today).  My favorite in this challenge.', '2014-04-25 00:33:10.000000', NULL, 1),
(7208103, 1109636, 108069, '<td valign="top">Wow, this is some photo, Mark. Haven''t had a chance to look through this challenge yet, but in any context this is a hell of a photo. Nicely done.</td>', 'Wow, this is some photo, Mark. Haven''t had a chance to look through this challenge yet, but in any context this is a hell of a photo. Nicely done.', '2014-04-25 01:03:20.000000', NULL, 0),
